#include <stdio.h>

void merge_sort(int *a, int *temporary, int lo, int hi) {
    if (hi - lo < 2) {
        return;
    }
    int mid = lo + (hi - lo) / 2;
    merge_sort(a, temporary, lo, mid);
    merge_sort(a, temporary, mid, hi);
    int i = lo;
    int j = mid;
    int k = lo;
    while (i < mid && j < hi) {
        if (a[i] <= a[j]) {
            temporary[k++] = a[i++];
        } else {
            temporary[k++] = a[j++];
        }
    }
    while (i < mid) {
        temporary[k++] = a[i++];
    }
    while (j < hi) {
        temporary[k++] = a[j++];
    }
    for (int position = lo; position < hi; ++position) {
        a[position] = temporary[position];
    }
}

